 $$('[data-case]').forEach(b=>b.onclick=async()=>{if(!await flushDraft())return;S.selected=b.dataset.case;S.form=null;casesPage();});if(isLead())$('#case-summary').onclick=()=>navigate('synthesis','case:'+c.id);else narrativeEditor('case',c.id);
