function narrativeEditor(kind,id){
 const p=prepareForm(kind,id,{verdict:'',answer:'',evidence:'',confidence:'',ratings:Object.fromEntries((S.report_review?.ratings||[]).map(x=>[x.key,null]))});
 const prompt=kind==='report_review'?(S.user.role==='psychologist'?'از نگاه خانواده بررسی کنید اعداد و نمودارها قابل فهم باشند، برداشت تشخیصی یا قطعی القا نشود و پیشنهادها برای والد قابل اجرا باشند.':'از نگاه سنجش بررسی کنید مخرج آمار، عدم‌قطعیت، دادهٔ ناکافی و اعتبار هر مقایسه به‌روشنی گزارش شده باشد.') : kind==='parent_question'?(S.user.role==='psychologist'?'تناسب رشدی و لحن بی‌طرف؛ احتمال فشار یا سوگیری والد؛ و اینکه آیا بهتر است بخشی از موضوع را مستقیم و بی‌فشار از کودک بپرسیم.':'ارتباط پاسخ با سازه یا عامل مزاحم؛ کدگذاری و کاربرد مجاز در گزارش؛ و اینکه چه چیزی نباید وارد نمره شود.') : '';
 $('#editor').innerHTML=`<h3>${kind==='parent_question'?'نظر تخصصی شما':'پاسخ تخصصی شما'}</h3>${prompt?`<div class="note small">${prompt}</div>`:''}<form id="review-form" class="review-form"><div class="grid2">${selectField('verdict','نظر شما دربارهٔ پیشنهاد',[['agree','موافقم'],['revise','با اصلاح موافقم'],['disagree','موافق نیستم'],['outside','خارج از تخصص من است']],p.verdict)}${selectField('confidence','اطمینان به این نظر',[['low','کم؛ نیاز به اطلاعات بیشتر'],['medium','متوسط'],['high','زیاد در حوزهٔ تخصص خودم']],p.confidence)}</div>${textareaField('answer',kind==='parent_question'?'ارزیابی تخصصی، نگرانی یا پیشنهاد شما':'توضیح، اصلاح پیشنهادی یا اطلاعات موردنیاز',p.answer,kind==='parent_question'?'چه چیزی روشن یا مبهم است؟ چه تغییری پیشنهاد می‌کنید؟':'پیشنهاد من این است که…؛ برای تصمیم به این اطلاعات نیاز دارم…')}${textareaField('evidence',kind==='parent_question'?'اثر پیشنهادی بر تحلیل و محدودیت استفاده (اختیاری)':'شواهد یا روش بررسی پیشنهادی (اختیاری)',p.evidence,kind==='parent_question'?'این پاسخ چه خروجی پشتیبانی می‌کند و چه برداشتی از آن مجاز نیست؟':'منبع، تجربهٔ مرتبط، طرح مطالعه، معیار تصمیم یا نمونهٔ عبارت…')}${kind==='report_review'?`<h4>امتیازدهی سریع از ۱ (ضعیف) تا ۵ (روشن و مناسب)</h4><p class="small muted">اگر موردی روشن نیست، امتیاز پایین‌تر بدهید و دلیل را در توضیح بنویسید.</p><div class="grid2">${(S.report_review?.ratings||[]).map(x=>[x.key,x.label]).map(([k,l])=>selectField('rating_'+k,l,[['','انتخاب کنید'],['1','۱ · نامفهوم/ضعیف'],['2','۲ · نیازمند اصلاح زیاد'],['3','۳ · قابل فهم با اصلاح'],['4','۴ · روشن'],['5','۵ · بسیار روشن']],p.ratings?.[k]??'')).join('')}</div>`:''}<div class="note small">اگر عدد یا آستانه پیشنهاد می‌دهید، مشخص کنید موقت است یا بر شواهدی تکیه دارد. متن توضیحی شما از انتخاب یک گزینه مهم‌تر است.</div>${formFoot()}</form>`;
 const read=()=>{const value=Object.fromEntries(new FormData($('#review-form')));if(kind==='report_review'){value.ratings={};for(const {key:k} of (S.report_review?.ratings||[])){const n=value['rating_'+k];value.ratings[k]=n?Number(n):null;delete value['rating_'+k];}}return value;};
 bindEditor(read);
}

const priorityLabel={critical:'ایراد مهم گزارش‌شده',disagreement:'اختلاف نظر',reviewed:'نظر دریافت شده',unreviewed:'در انتظار داوری'};
function synthesisPage(){
 if(!isLead())return;
 const a=S.admin;const counts=a.stats;
 $('#page').innerHTML=`<div class="page-head"><div><div class="eyebrow">تحلیل‌گر اصلی · تبدیل نظر به اقدام</div><h1>جمع‌بندی شواهد، بدون قطعیت کاذب</h1><p>فقط نظرهای نهاییِ همین نسخه در شاخص‌ها شمرده می‌شوند؛ پیش‌نویس‌ها برای پیگیری جدا دیده می‌شوند.</p></div><div class="row wrap"><a class="btn secondary small" href="${BASE}/api/export?format=json">${icon('download')} خروجی کامل JSON</a><a class="btn outline small" href="${BASE}/api/export?format=csv">CSV نظرها</a></div></div><div class="grid4">${stat(counts.reviewed_items,'سؤال با نظر نهایی','bank')}${stat(counts.critical,'سؤال با ایراد مهم','eye')}${stat(counts.disagreements,'سؤال با اختلاف اقدام','users')}${stat(counts.submitted,'نظر نهایی در همهٔ بخش‌ها','check')}</div><div class="space"></div><div class="note small">این صف، ابزار مدیریت داوری است. «ایراد مهم» یعنی حداقل یک داور مشکل کلید یا اصلاح اساسی/حذف گزارش کرده است؛ «اختلاف» یعنی پیشنهاد اقدام متفاوت است. هیچ‌کدام حکم آماری یا تشخیص روان‌شناختی نیست.</div><div class="section-title"><h2>انتخاب موضوع برای بررسی</h2></div><div class="grid2"><div><label for="summary-kind">نوع موضوع</label><select id="summary-kind"><option value="item">سؤال‌ها</option><option value="decision">تصمیم‌های تخصصی</option><option value="case">تفسیر پاسخ‌ها</option><option value="parent_question">پرسش‌های پیش از آزمون</option></select></div><div><label for="summary-filter">صف بررسی سؤال</label><select id="summary-filter"><option value="all">همهٔ سؤال‌ها</option><option value="critical">ایراد مهم</option><option value="disagreement">اختلاف نظر</option><option value="reviewed">نظر دریافت شده</option><option value="unreviewed">منتظر داوری</option></select></div></div><div class="space"></div><div id="summary-table"></div><div id="summary-detail"></div><div class="section-title"><h2>شکاف‌های فعلی تحلیل من</h2></div><div class="grid3"><div class="card"><h3>کیفیت محتوا</h3><p class="small muted">هنوز برای اکثر سؤال‌ها داوری مستقل نداریم. موارد تکراری، کلید، گزینه‌های ضعیف و انتقال ناهم‌سطح باید بررسی شوند.</p></div><div class="card"><h3>اعتبار مدل</h3><p class="small muted">تک‌بعدی‌بودن، پارامتر سؤال‌ها و دقت برآورد معلوم نیست؛ یک نمرهٔ کلی یا صدک قابل انتشار نداریم.</p></div><div class="card"><h3>تجربهٔ کودک</h3><p class="small muted">مصاحبهٔ فهم‌پذیری و نمایش مناسب A اجرا نشده؛ داوری بزرگسال جای مشاهدهٔ کودک را نمی‌گیرد.</p></div></div>`;
 const selected=S.selected||'';let kind=selected.includes(':')?selected.split(':')[0]:'item';if(!['item','case','decision','parent_question'].includes(kind))kind='item';$('#summary-kind').value=kind;
 const draw=()=>{kind=$('#summary-kind').value;const filter=$('#summary-filter').value;$('#summary-filter').disabled=kind!=='item';
  const list=kind==='item'?a.items.filter(i=>filter==='all'||i.priority===filter):a.decisions.filter(i=>i.kind===kind);
  $('#summary-table').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>موضوع</th><th>نظر نهایی معتبر</th><th>وضعیت</th><th>اقدام</th></tr></thead><tbody>${list.map(i=>{const item=kind==='item'?S.bank.items.find(x=>x.id===i.id):null;return `<tr><td><strong>${esc(item?.title||i.title)}</strong>${item?`<div class="mono muted">${i.id}</div>`:''}</td><td>${fa(i.n)} ${kind==='item'?`<div class="small muted">تناسب: ${fa(i.relevance_agree)} از ${fa(i.relevance_n)} داور، امتیاز ۳ یا ۴</div>`:''}</td><td><span class="pill ${i.priority==='critical'?'red':i.priority==='disagreement'||i.needs_attention?'amber':'neutral'}">${kind==='item'?priorityLabel[i.priority]:i.n?(i.needs_attention?'نیازمند بررسی':'نظر دریافت شده'):'منتظر نظر'}</span></td><td><button class="btn outline small" data-summary="${i.id}">بازکردن</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">موردی در این صف نیست.</div>';
  $$('[data-summary]').forEach(b=>b.onclick=()=>showSummary(kind,b.dataset.summary));
 };
 $('#summary-kind').onchange=()=>{$('#summary-detail').innerHTML='';draw();};$('#summary-filter').onchange=draw;draw();
 if(selected)showSummary(kind,selected.includes(':')?selected.split(':').slice(1).join(':'):selected,false);
}
function showSummary(kind,id,scroll=true){
 const x=kind==='item'?S.bank.items.find(i=>i.id===id):kind==='case'?S.cases.find(i=>i.id===id):kind==='parent_question'?S.parent_questions.find(i=>i.id===id):S.decisions.find(i=>i.id===id);if(!x)return;
 S.selected=(kind==='item'?'':kind+':')+id;const a=S.admin;const reviews=a.reviews.filter(r=>r.kind===kind&&r.target===id);const currentVersion=versionOf(kind,id);
 const res=a.resolutions.find(r=>r.kind===kind&&r.target===id&&r.target_version===currentVersion);
 const actions={accept:'مناسب مرحلهٔ بعد',minor:'اصلاح جزئی',major:'اصلاح اساسی',reject:'حذف',outside:'خارج از تخصص',agree:'موافق',revise:'با اصلاح',disagree:'مخالف'};
 $('#summary-detail').innerHTML=`<section class="card review-detail"><div class="row between wrap"><h2>${esc(x.title)}</h2><span class="mono muted">${esc(id)}</span></div>${kind==='item'?`<p class="small muted">${esc(x.stem)}</p><button class="text-btn" id="open-source-item">دیدن کارت کامل سؤال ←</button>`:`<p class="small muted">${esc(kind==='parent_question'?x.prompt:(x.proposed||x.proposal))}</p>${kind==='parent_question'?`<div class="callout"><b>هدف پرسش:</b> ${esc(x.why)}<br><b>خروجی مورد انتظار:</b> ${esc(x.output)}</div>`:''}`}<div class="analyst-grid"><div><h3>نظرهای مستقل</h3>${reviews.length?reviews.map(r=>`<article class="reviewer-comment"><div class="row between wrap"><strong class="small">${esc(r.name)} · ${esc(S.roles[r.role])}</strong><span class="pill ${r.status==='submitted'?'green':'amber'}">${r.status==='submitted'?'نهایی':'پیش‌نویس؛ وارد جمع‌بندی نمی‌شود'}</span></div>${r.target_version!==currentVersion?'<p class="small" style="color:var(--red)">این نظر مربوط به نسخهٔ قبلی است؛ در شاخص‌های فعلی شمرده نمی‌شود.</p>':''}<p class="small">نظر: <strong>${esc(actions[r.payload.action||r.payload.verdict]||'تعیین نشده')}</strong> · اطمینان: ${esc({low:'کم',medium:'متوسط',high:'زیاد'}[r.payload.confidence]||'مشخص نشده')}</p>${r.kind==='item'?`<div class="tag-list">${Object.entries(r.payload.ratings||{}).filter(([,v])=>v!=null).map(([k,v])=>`<span class="pill neutral">${esc(S.ratings.find(t=>t.key===k)?.label)}: ${fa(v)}</span>`).join('')}</div><p class="small">کلید: ${esc({correct:'درست و یکتا',wrong:'مشکل کلید',ambiguous:'چند پاسخ قابل دفاع',unsure:'نامشخص'}[r.payload.key_verdict]||'—')}</p>`:''}${Object.entries(r.payload).filter(([k,v])=>typeof v==='string'&&v&&['notes','rewrite','confound','transfer_notes','answer','evidence'].includes(k)).map(([k,v])=>`<blockquote><strong>${{notes:'دلیل',rewrite:'بازنویسی',confound:'عامل مزاحم',transfer_notes:'راهنما و انتقال',answer:'توضیح',evidence:'شواهد و روش'}[k]}:</strong> ${esc(v)}</blockquote>`).join('')}<div class="small muted" style="margin-top:10px">ویرایش ${fa(r.revision)} · ${new Date(r.updated*1000).toLocaleString('fa-IR')}</div></article>`).join(''):'<div class="empty"><strong>هنوز نظری ثبت نشده</strong>برای این موضوع دعوت تخصصی بفرستید یا منتظر تکمیل بررسی بمانید.</div>'}</div><aside><div class="note small"><strong>تحلیل من برای اقدام بعدی</strong><p style="margin-top:9px">${analysisSuggestion(kind,id)}</p><p>دلیل‌های داوران را بخوانید؛ فراوانی موافقت جای کیفیت استدلال را نمی‌گیرد. اصلاح بانک یا الگوریتم خودکار نیست.</p></div><form id="resolution-form"><h3 style="margin-top:23px">تصمیم تحلیل‌گر پروژه</h3>${selectField('decision','اقدام بعدی',[['needs_revision','بازنویسی / اصلاح'],['needs_evidence','جمع‌آوری شواهد بیشتر'],['ready_for_pilot_review','ارجاع به بررسی آمادگی پایلوت'],['hold','تعلیق این مورد']],res?.decision||'')}${textareaField('reason','دلیل تصمیم و کار مشخص بعدی',res?.reason||'','مثلاً صورت سؤال بازنویسی و برای دو داور فرستاده شود؛ هنوز مجاز به اجرای نمره‌دار نیست.')}<button class="btn" type="submit">ثبت اقدام تحلیل‌گر</button><p id="resolution-status" class="small muted"></p></form></aside></div></section>`;
 if(kind==='item')$('#open-source-item').onclick=()=>navigate('bank',id);if(kind==='parent_question')$('#open-source-item')?.remove();
 $('#resolution-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/resolution',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),kind,target:id})});S.admin=await api('/api/admin');$('#resolution-status').textContent='اقدام ثبت شد؛ انتشار یا تغییر بانک انجام نشده است.';toast('تصمیم تحلیل‌گر ذخیره شد.');}catch(err){toast(err.message,true);}};
 if(scroll)$('#summary-detail').scrollIntoView({behavior:'smooth',block:'start'});
}
function analysisSuggestion(kind,id){
 const rs=S.admin.reviews.filter(r=>r.kind===kind&&r.target===id&&r.status==='submitted'&&r.target_version===versionOf(kind,id));
 if(!rs.length)return 'برای این نسخه هنوز نظر نهایی نداریم. موضوع در انتظار داوری می‌ماند؛ نتیجهٔ مثبت یا منفی استنباط نمی‌شود.';
 if(kind==='item'){
  const wrong=rs.filter(r=>['wrong','ambiguous'].includes(r.payload.key_verdict));if(wrong.length)return 'حداقل یک ایراد دربارهٔ کلید یا یکتایی پاسخ گزارش شده است. ابتدا استدلال منطقی و متن بازبینی شود؛ این کارت تا رفع ابهام وارد پایلوت نشود.';
  const major=rs.filter(r=>['major','reject'].includes(r.payload.action));if(major.length)return 'حداقل یک داور اصلاح اساسی یا حذف پیشنهاد کرده است. دلیل را با هدف سنجش تطبیق دهید و نسخهٔ اصلاح‌شده را دوباره برای داوری بفرستید.';
  if(new Set(rs.map(r=>r.payload.action)).size>1)return 'پیشنهاد اقدام داوران متفاوت است. علت اختلاف را بررسی و در صورت نیاز سؤال روشنگر مشخصی مطرح کنید؛ میانگین‌گیری به‌تنهایی اختلاف را حل نمی‌کند.';
 }
 return 'نظرهای موجود را همراه با نقش و میزان اطمینان بخوانید. شواهد محتوایی دریافت شده است؛ مجوز گزارش نمره یا فعال‌کردن CAT همچنان به مطالعهٔ میدانی وابسته است.';
}

function teamPage(){
 const a=S.admin;
 $('#page').innerHTML=`<div class="page-head"><div><div class="eyebrow">همکاری مستقل چند متخصص</div><h1>برای هر ارزیاب، یک دعوت شخصی</h1><p>هر نفر حساب خودش را می‌سازد؛ پاسخ‌ها با هم مخلوط نمی‌شوند.</p></div><a class="btn secondary small" href="${BASE}/api/admin/backup">${icon('download')} پشتیبان کامل</a></div><div class="grid2"><section class="card"><h3>ساخت لینک دعوت</h3><p class="small muted">دعوت‌نامه یک‌بارمصرف و ۳۰ روز معتبر است. فقط آن را برای فرد موردنظر بفرستید.</p><form id="invite-form"><div class="field"><label for="invite-label">نام یا عنوان دعوت</label><input id="invite-label" name="label" required maxlength="100" placeholder="مثلاً دکتر … / داور اول"></div>${selectField('role','حوزهٔ تخصص',[['psychometrician','روان‌سنج'],['psychologist','روان‌شناس کودک'],['content','متخصص آموزش و منطق']],'psychometrician')}<div class="field"><label for="invite-host">نشانی قابل استفاده برای ارزیاب</label><select id="invite-host"><option value="${esc(location.origin)}">همین رایانه · ${esc(location.origin)}</option>${a.network_urls.filter(u=>u!==location.origin).map(u=>`<option value="${esc(u)}">شبکهٔ داخلی · ${esc(u)}</option>`).join('')}</select></div><button class="btn" type="submit">ساخت دعوت‌نامه ${icon('users')}</button></form><div id="invite-result"></div></section><section class="card"><h3>روش تحویل به همکار</h3><div class="timeline-step"><span class="step-number">۱</span><div><strong class="small">نقش را مشخص کنید</strong><p>فرم تصمیم‌ها بر اساس تخصص نمایش داده می‌شود. متخصص لازم نیست دربارهٔ برنامه‌نویسی یا دیتابیس نظر دهد.</p></div></div><div class="timeline-step"><span class="step-number">۲</span><div><strong class="small">لینک را شخصاً ارسال کنید</strong><p>روی همین رایانه لینک محلی کافی است. روی رایانه‌های دیگر، هر دو دستگاه باید به همین شبکه دسترسی داشته باشند و سرور روشن بماند.</p></div></div><div class="timeline-step"><span class="step-number">۳</span><div><strong class="small">نظرها را جمع‌بندی کنید</strong><p>فقط فرم‌های نهایی وارد صف تصمیم می‌شوند. لینک عمومی اینترنتی در این نسخه راه‌اندازی نشده است.</p></div></div><div class="note warning small">دسترسی شبکه ممکن است به تنظیمات موجود فایروال بستگی داشته باشد. برای همکاری اینترنتی، استقرار HTTPS و پشتیبان‌گیری روی سرور لازم است؛ لینک 127.0.0.1 روی دستگاه دیگر به این رایانه وصل نمی‌شود.</div></section></div><div class="section-title"><h2>ارزیاب‌های عضو شده</h2><span class="pill">${fa(a.users.length)} نفر</span></div>${a.users.length?`<div class="table-wrap"><table><thead><tr><th>نام</th><th>تخصص</th><th>نظر نهایی</th><th>پیش‌نویس</th></tr></thead><tbody>${a.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><div class="muted small">${esc(u.username)}</div></td><td>${esc(S.roles[u.role])}</td><td>${fa(a.reviews.filter(r=>r.user_id===u.id&&r.status==='submitted').length)}</td><td>${fa(a.reviews.filter(r=>r.user_id===u.id&&r.status==='draft').length)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>هنوز ارزیابی عضو نشده است</strong>با ساخت اولین دعوت‌نامه، همکاری را شروع کنید.</div>'}<div class="section-title"><h2>سابقهٔ دعوت‌نامه‌ها</h2></div>${a.invites.length?`<div class="table-wrap"><table><thead><tr><th>دعوت</th><th>نقش</th><th>وضعیت</th></tr></thead><tbody>${a.invites.map(i=>`<tr><td>${esc(i.label)}</td><td>${esc(S.roles[i.role])}</td><td>${i.used_by?'استفاده شده':i.expires*1000<Date.now()?'منقضی':'منتظر عضویت'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">دعوت‌نامه‌ای ساخته نشده است.</p>'}`;
 $('#invite-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const d=await api('/api/admin/invites',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const link=$('#invite-host').value+BASE+d.path;$('#invite-result').innerHTML=`<div class="invite-result"><strong class="small">دعوت‌نامه آماده است</strong><p class="small">لینک زیر را فقط برای همین ارزیاب بفرستید؛ بعد از مصرف از سابقه قابل بازیابی نیست.</p><input readonly id="invite-link" value="${esc(link)}" aria-label="لینک دعوت"><button class="btn secondary small" style="margin-top:10px" id="copy-invite">کپی لینک</button></div>`;$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('لینک دعوت کپی شد.');}catch{$('#invite-link').select();toast('لینک انتخاب شد؛ با Ctrl+C کپی کنید.');}};S.admin=await api('/api/admin');}catch(err){toast(err.message,true);}finally{b.disabled=false;}};
}

function implementationPage(){
 $('#page').innerHTML=`<div class="page-head"><div><div class="eyebrow">تحلیل‌گر و تیم توسعه</div><h1>نقشهٔ پیاده‌سازی، فراتر از دیتابیس</h1><p>تفکیک آنچه در این برنامه ساخته شده، آنچه طراحی شده و آنچه نیازمند شواهد است.</p></div><div class="row wrap"><a class="btn secondary small" href="${BASE}/static/IMPLEMENTATION.md" download>${icon('download')} سند کامل پیاده‌سازی</a><a class="btn secondary small" href="${BASE}/api/admin/question-bank">دانلود بانک کامل با پاسخ</a><a class="btn secondary small" href="${BASE}/api/admin/selection-engine">دانلود نمونهٔ انتخاب‌گر</a><a class="btn secondary small" href="${BASE}/static/parent-intake-preview.html" target="_blank" rel="noopener">نمونهٔ پرسش‌های والدین</a><button class="btn secondary small" data-go="parent_questions">داوری پرسش‌ها توسط متخصص</button><a class="btn secondary small" href="${BASE}/static/PHASE_TWO_HANDOFF.md" download>مشخصات فاز دوم</a><a class="btn secondary small" href="${BASE}/static/adaptive-selection-spec.md" download>الگوریتم انتخاب سؤال</a><a class="btn secondary small" href="${BASE}/static/sample-report.html" target="_blank" rel="noopener">نمای کارنامهٔ والد</a></div></div><div class="notice">${icon('code')}<div><strong>این برنامه میزکار تحلیل است، نه سامانهٔ اجرای آزمون کودک.</strong><br>ثبت نظر، دعوت ارزیاب، سابقهٔ ویرایش، جمع‌بندی و خروجی اجرا شده‌اند. اجرای CAT کالیبره، نمره‌گذاری هنجاری، اتصال Oracle و گزارش خودکار والد هنوز ساخته نشده‌اند. نمونهٔ داشبورد و فرم داوری پرسش‌های والد در دسترس است.</div></div><div class="space"></div><section class="card"><h2>زنجیرهٔ کامل محصول پیشنهادی</h2><div class="technical-flow">${[['۱','مدیریت بانک','نگارش، نسخه، داوری'],['۲','پایلوت','فرم چرخشی، پاسخ معتبر'],['۳','تحلیل و مدل','برازش، کالیبراسیون، انصاف'],['۴','اجرای تطبیقی','انتخاب، پوشش، توقف'],['۵','گزارش','شواهد، قواعد، بازبینی']].map(([n,t,d])=>`<div class="technical-step"><span class="pill">${n}</span><b>${t}</b><span class="muted">${d}</span></div>`).join('')}</div><div class="spec-section"><h3>۱. رفتار تجربهٔ کودک</h3><p>رضایت و موافقت کودک ← آشنایی غیرنمره‌دار با رابط و نماد ← قطب‌نمای کوتاه ← ادامهٔ فناوری با تمایل و شواهد کافی ← چرخه‌های از پیش مشخص اولیه/راهنما/انتقال ← پایان با علت روشن. استراحت و خروج همیشه آزاد است. علاقه از جواب درست یا سرعت کلیک استخراج نمی‌شود.</p></div><div class="spec-section"><h3>۲. انتخاب سؤال و قرارداد خطا</h3><p>فیلتر سن، انتشار، نقش، خانوادهٔ تکراری، کالیبراسیون و سقف نمایش؛ سپس اولویت پوشش محتوا؛ سپس اطلاعات سؤال و انتخاب کنترل‌شده. اگر نامزد معتبر نیست، BANK_EXHAUSTED ثبت شود؛ سؤال نمره‌دار جدید در لحظه تولید نشود. SEE یا تعداد پاسخ به‌تنهایی جای پوشش مهارت را نمی‌گیرد.</p></div><div class="spec-section"><h3>۳. ثبت پاسخ و بازیابی نشست</h3><p>هر نمایش شناسهٔ مستقل دارد. پاسخ اولیه یک بار نهایی می‌شود. request_id و نسخهٔ نشست از ثبت دوگانه جلوگیری می‌کنند؛ دریافت مجدد همان درخواست همان نتیجه را برمی‌گرداند. ردکردن، خرابی رابط و دادهٔ نامعتبر با غلط متفاوت‌اند. کمک و انتقال به برآورد عملکرد بدون کمک وارد نمی‌شوند.</p></div><div class="spec-section"><h3>۴. موتور تحلیل پاسخ‌ها</h3><p>ورودی فقط پاسخ اولیهٔ معتبر و بدون کمک در نسخهٔ مشخص است. در پایلوت آمار توصیفی و کیفیت داده؛ بعد از تأیید مدل، برآورد توانایی همراه عدم‌قطعیت. درصد درست، گزینه‌ها، عدم پاسخ، زمان، برازش و انصاف مخرج و شرایط ورود روشن دارند. برچسب گزینهٔ غلط تشخیص شناختی نیست.</p></div><div class="spec-section"><h3>۵. گزارش و بازبینی</h3><p>سرور بستهٔ شواهد ارجاع‌دار می‌سازد؛ قواعد حدود تفسیر را اعمال می‌کنند؛ متن پیشنهادی می‌تواند با مدل یا قالب ثابت ساخته شود؛ اعداد و ارجاع‌ها مستقل کنترل و در نسخهٔ نخست با انسان بازبینی شوند. دادهٔ ناموجود صفر نیست و ادعای شغلی یا بالینی از این تکلیف‌ها تولید نمی‌شود.</p></div><div class="spec-section"><h3>۶. معماری و راه‌اندازی میزکار فعلی</h3><p>رابط فارسی HTML/CSS/JavaScript، سرور Python با Flask و Waitress، SQLite با ثبت نسخهٔ نظر و تاریخچه. مسیر هر کاربر جداست؛ سرور مجوز را بررسی می‌کند. توکن نشست HttpOnly و CSRF، دعوت یک‌بارمصرف، رمز هش‌شده و خروجی بدون رمز و توکن داریم. لینک محلی برای همین دستگاه و لینک شبکه برای شبکهٔ داخلی است.</p></div><div class="spec-section"><h3>۷. دروازه‌های تحویل محصول اصلی</h3><div class="table-wrap"><table><thead><tr><th>تحویل</th><th>معیار پذیرش</th></tr></thead><tbody><tr><td>بانک داوری‌شده</td><td>کلید یکتا، زبان قابل فهم، نسخهٔ ثابت، خانواده و راهنمای روشن</td></tr><tr><td>پایلوت قابل اجرا</td><td>فرم‌های متوازن، ثبت فاز مستقل، قطع و ادامه، رضایت و کیفیت داده</td></tr><tr><td>مدل تأییدشده</td><td>ساختار درونی، پارامتر و خطا، انصاف، حد مجاز تفسیر</td></tr><tr><td>CAT محدود</td><td>شبیه‌سازی خطا، پوشش، نمایش، توقف و اتمام بانک؛ سپس اجرای کنترل‌شده</td></tr><tr><td>گزارش والد</td><td>هر ادعا ارجاع معتبر، دادهٔ ناکافی روشن، بازبینی و جداسازی سازه‌ها</td></tr></tbody></table></div></div><div class="note small">جزئیات ماژول‌ها، APIهای موجود، مدل داده، تست‌ها، پشتیبان و شکاف‌های پیاده‌سازی در سند قابل دریافت بالای صفحه آمده است. طراحی ۲۵ جدول Oracle، طرح محصول اصلی است؛ SQLite این میزکار جایگزین بی‌اعلام آن نیست.</div></section>`;
 bindGo();
}
function guidePage(){
 $('#page').innerHTML=`<div class="page-head"><div><div class="eyebrow">راهنمای قابل استفاده در اولین ورود</div><h1>از کجا شروع کنم و چه چیزی تحویل بدهم؟</h1><p>لازم نیست ساختار فنی پروژه را بدانید؛ مسئولیت شما مشخص و محدود است.</p></div></div><section class="card"><h2>دیدبان چیست و امروز چه کاری دارم؟</h2><p>ما می‌خواهیم قبل از اجرای سنجش آموزشی فناوری، متن سؤال‌ها و برداشت‌های پیشنهادی از پاسخ کودک را بررسی کنیم. شما طراح کل پروژه نیستید؛ نظر تخصصی کوتاه شما به تحلیل‌گر کمک می‌کند اشتباه‌های طرح را پیدا کند.</p><ol class="check-list"><li>از منوی «شروع مرحله‌به‌مرحله» بستهٔ شروع را باز کنید؛ روان‌شناس شش سؤال نمونه و روان‌سنج دو تصمیم ضروری دارد.</li><li>متن را بخوانید. اگر یک واژه سخت است یا سؤال خسته‌کننده به نظر می‌رسد، همان را کوتاه بنویسید.</li><li>برای روشنی متن و تناسب سن، ۱ یعنی مشکل جدی، ۲ یعنی اصلاح زیاد، ۳ یعنی اصلاح کم و ۴ یعنی مناسب از نگاه شما. اگر نمی‌دانید، گزینهٔ مربوط را انتخاب کنید.</li><li>در «پاسخ پیشنهادی طراح» اگر منطق کد را بررسی نکرده‌اید «در حوزهٔ من نیست / مطمئن نیستم» را بزنید. این پاسخ هیچ امتیاز منفی ندارد.</li><li>اقدام پیشنهادی و میزان اطمینان را مشخص و «ثبت نهایی نظر» را بزنید. سپس مورد بعدی را بررسی کنید.</li><li>یک سناریوی فرضی را تفسیر کنید؛ بعد از آن کار اولیه تمام است. هر زمان می‌توانید خارج شوید و بعداً ادامه دهید.</li></ol><div class="note">نمونهٔ نظر مفید: «واژهٔ متغیر برای این سن آشنا نیست؛ پیش از سؤال یک مثال روزمره اضافه شود.» لازم نیست مقاله یا گزارش طولانی بنویسید. بررسی بقیهٔ بانک و معیارهای تکمیلی اختیاری است.</div></section><div class="space"></div><div class="grid2"><section class="card"><h3>نقش شما: ${esc(roleName())}</h3><p>${isLead()?'شما مسئول پیشنهاد اولیه، سازمان‌دهی داوری‌ها، خواندن دلیل اختلاف و ثبت اقدام بعدی هستید. متخصص فقط دربارهٔ حوزهٔ خودش کمک می‌کند.':S.user.role==='psychologist'?'روی فهم کودک، زبان، بار تکلیف، تجربهٔ هیجانی، علاقه و عبارت‌های گزارش تمرکز کنید. اگر صحت کد یا مدل آماری خارج از حوزهٔ شماست، همان را مشخص کنید.':S.user.role==='psychometrician'?'روی تناسب تکلیف با سازه، پوشش مهارت، شواهد لازم، طرح پایلوت، روش تحلیل پاسخ‌ها و حدود تفسیر تمرکز کنید. از شما پارامتر عددی حدسی نمی‌خواهیم.':'روی صحت منطق، یکتایی کلید، پیش‌نیازهای آموزشی، کیفیت گزینه‌ها و استقلال مسئلهٔ تازه تمرکز کنید.'}</p><div class="note small">تحلیل‌گر اصلی طراحی فنی و جمع‌بندی را انجام می‌دهد؛ شما مجبور نیستید دربارهٔ موضوع خارج از تخصص پاسخ قطعی بدهید.</div></section><section class="card"><h3>یک بررسی کامل چه شکلی است؟</h3><ol class="check-list small"><li>سؤال را بخوانید؛ اگر مبهم بود توضیح و دلیل پاسخ را باز کنید.</li><li>راهنما و سؤال تازه را جدا بررسی کنید.</li><li>داوری مربوط به تخصص خود و دلیل را بنویسید.</li><li>برای اصلاح مهم، متن مشکل و راه‌حل یا اطلاعات لازم را مشخص کنید.</li><li>ثبت نهایی کنید؛ بعداً هم قابل اصلاح است.</li></ol></section></div><div class="section-title"><h2>اصطلاحات به زبان ساده</h2></div><div class="grid3">${[['هدف سنجش','همان مهارتی که سؤال قرار است نشانه‌ای از آن بدهد؛ مثلاً توجه به مرز یک شرط.'],['تلاش اولیه','پاسخ کودک پیش از دیدن هر راهنمایی؛ برای تحلیل عملکرد بدون کمک.'],['انتقال','حل یک مسئلهٔ تازه پس از راهنما؛ موفقیت در آن به‌تنهایی اثبات سرعت یادگیری نیست.'],['خانوادهٔ سؤال','چند سؤال با ساختار بسیار مشابه؛ پاسخ‌های آنها لزوماً شواهد مستقل نیستند.'],['کالیبراسیون','برآورد ویژگی سؤال با پاسخ واقعی شرکت‌کننده‌ها؛ برچسب آسان/سخت طراح کالیبراسیون نیست.'],['ثبت نهایی نظر','نظر فعلی شما آمادهٔ جمع‌بندی است؛ به معنی تأیید کل آزمون یا انتشار سؤال نیست.']].map(([t,d])=>`<article class="card"><h3>${t}</h3><p class="small muted">${d}</p></article>`).join('')}</div><div class="section-title"><h2>ذخیره، حریم داده و ادامهٔ کار</h2></div><section class="card"><p>تغییرهای فرم با کمی مکث در همین سرور به‌صورت پیش‌نویس ذخیره می‌شوند. وضعیت ذخیره پایین فرم دیده می‌شود. اگر اتصال قطع شود، متن در همین مرورگر نگه داشته می‌شود و هنگام بازکردن همان فرم قابل بازیابی است؛ گزینهٔ خروجی متن فرم هم دارید. در تعارض دو پنجره، فرم روی سرور بدون اطلاع شما بازنویسی نمی‌شود.</p><p>نام و نظر ارزیاب برای تحلیل‌گر قابل مشاهده است؛ سایر ارزیاب‌ها آن را نمی‌بینند. داده به سرویس هوش مصنوعی ارسال نمی‌شود. این میزکار برای نظر تخصصی است؛ نام، شرح‌حال یا پاسخ واقعی کودک را وارد نکنید. بانک و نظرات در پوشهٔ پروژه روی رایانهٔ میزبان می‌مانند.</p><div class="row wrap"><a href="${BASE}/api/export?format=json" class="btn secondary small">${icon('download')} ${isLead()?'خروجی کل پروژه':'دریافت نظرهای خودم'}</a><a href="${BASE}/api/export?format=csv" class="btn outline small">خروجی CSV</a>${isLead()?`<a href="${BASE}/api/admin/backup" class="btn outline small">پشتیبان کامل پروژه</a>`:''}</div></section><div class="section-title"><h2>منابع راهنمای طراحی</h2><span class="pill neutral">این منابع بانک حاضر را تأیید نمی‌کنند</span></div><section class="card">${S.sources.map(x=>`<a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(x.title)}</strong><br><span class="muted small">${esc(x.use)}</span></span>${icon('arrow')}</a>`).join('')}</section>`;
}
function starterPage(){
 const plan=S.phase_one;
 const ids=S.user.role==='psychometrician'?plan.psychometric_decision_ids:plan.item_ids;
 const kind=S.user.role==='psychometrician'?'decision':'item';
 const done=ids.filter(id=>reviewOf(kind,id)?.status==='submitted').length;
 const next=ids.find(id=>reviewOf(kind,id)?.status!=='submitted');
 const caseId=plan.case_ids[0]; const caseDone=!caseId||reviewOf('case',caseId)?.status==='submitted';
 $('#page').innerHTML=`<section class="hero"><div><div class="eyebrow">فاز اول · شروع کوتاه</div><h1>${esc(S.user.name)}، خوش آمدید</h1><p>دیدبان کمک می‌کند سؤال‌های سنجش آموزشی فناوری برای کودکان ۸ تا ۱۶ سال روشن‌تر و مناسب‌تر شوند. پیشنهاد اولیه آماده است؛ شما آن را از نگاه تخصص خود بررسی می‌کنید.</p><span class="pill">${esc(plan.estimated_minutes)}</span></div></section>${S.user.is_test?'<div class="notice">حساب آزمایشی: نظرهای این حساب در نتایج واقعی و شمار توافق متخصصان وارد نمی‌شوند.</div>':''}<div class="grid3">${stat(done,'بررسی کوتاه نهایی‌شده','check')}${stat(ids.length-done,'بررسی باقی‌مانده در بستهٔ شروع','clock')}${stat(caseDone?1:0,'سناریوی تفسیر تکمیل‌شده','cases')}</div><section class="card"><h2>از همین‌جا شروع کنید</h2><div class="timeline-step"><span class="step-number">۱</span><div><h3>بدانید قرار است چه کار کنید</h3><p>${S.user.role==='psychometrician'?'در شروع فقط دو تصمیم پیشنهادی دربارهٔ سنجش را بخوانید. نیازی به بررسی تمام بانک یا تخمین پارامتر آماری نیست.':'شش سؤال نمونه از سه گروه سنی را بخوانید. دربارهٔ روشن‌بودن متن و تناسب با سن نظر دهید؛ لازم نیست کد یا مدل آماری را تأیید کنید.'}</p><button class="btn secondary small" data-go="guide">راهنمای ساده و مثال</button></div></div><div class="timeline-step"><span class="step-number">۲</span><div><h3>یک بررسی کوتاه ثبت کنید</h3><p>متن و توضیح را بخوانید؛ گزینه‌ها را انتخاب و اگر مشکلی هست یک جمله دلیل بنویسید. «ثبت نهایی نظر» را بزنید. پیش‌نویس هنوز نظر نهایی نیست.</p><button class="btn" id="start-next">${next?'ادامه از اولین مورد ناتمام':'مرور بستهٔ تکمیل‌شده'}</button></div></div><div class="timeline-step"><span class="step-number">۳</span><div><h3>یک موقعیت فرضی را تفسیر کنید</h3><p>بگویید از این موقعیت چه می‌فهمیم و چه چیزی را هنوز نمی‌توان نتیجه گرفت. این سناریو، نتیجهٔ آزمون واقعی کودک نیست.</p><button class="btn secondary small" data-go="cases" data-target="${esc(caseId||'')}">${caseDone?'مرور تفسیر ثبت‌شده':'بازکردن سناریو'}</button></div></div><div class="timeline-step"><span class="step-number">۴</span><div><h3>${done===ids.length&&caseDone?'کار اولیهٔ شما تمام شده است':'بعد از تکمیل، تحلیل‌گر ادامه می‌دهد'}</h3><p>نظرها با نام شما ذخیره می‌شوند. تحلیل‌گر ایرادها و اختلاف‌ها را جمع‌بندی می‌کند؛ روان‌سنج در مرحلهٔ اول فقط تصمیم‌های ضروری و موارد ارجاع‌شده را بررسی می‌کند. بررسی بقیهٔ بانک اختیاری است.</p></div></div><div class="note warning">${esc(plan.purpose)} نظر مثبت روی نمونه‌ها تأیید کل آزمون یا مجوز نمره‌گذاری کودک نیست.</div></section>`;
 bindGo();$('#start-next').onclick=()=>{S.quickFilter=true;S.filters={band:'',dim:'',level:'',status:'',search:''};navigate(kind==='item'?'bank':'decisions',next||ids[0]);};
}
function analysisPage(){
 const labels={supported:'پشتیبانی شد',contradicted:'نیازمند اصلاح / ناسازگار با شواهد',inconclusive:'شواهد ناکافی'};
 $('#page').innerHTML=`<div class="page-head"><div><h1>دفتر تحلیل و شواهد</h1><p>فرض اولیه، شاهد مخالف یا موافق و تصمیم بعدی را ثبت کنید تا مسیر اصلاح تحلیل قابل پیگیری بماند.</p></div></div><section class="card"><form id="analysis-form">${textareaField('hypothesis','فرض اولیهٔ من چه بود؟','','مثلاً متن شرط برای گروه B روشن است.')}${textareaField('evidence','چه شاهدی داریم؟ شناسهٔ نظر یا سؤال و دلیل','','مثلاً نظر شمارهٔ ۱۲، سؤال B-COND-01: واژهٔ شرط مبهم بود.')}${selectField('outcome','نتیجهٔ بررسی',Object.entries(labels),'inconclusive')}${textareaField('next_action','چه چیزی را تغییر می‌دهیم یا بررسی می‌کنیم؟','','اقدام مشخص و شاهد لازم برای بررسی دوباره')}<button class="btn" type="submit">ثبت در دفتر تحلیل</button></form></section><div class="section-title"><h2>سابقهٔ بررسی فرض‌ها</h2></div>${S.admin.analysis_log.map(x=>`<article class="card"><span class="pill">${esc(labels[x.outcome])}</span><h3>${esc(x.hypothesis)}</h3><p>شاهد: ${esc(x.evidence||'هنوز ثبت نشده')}</p><p>اقدام بعدی: ${esc(x.next_action)}</p></article>`).join('')||'<div class="empty">هنوز فرضی ثبت نشده؛ نبود داده به معنی درست یا غلط بودن تحلیل نیست.</div>'}`;
 $('#analysis-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{await api('/api/admin/analysis',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await render();toast('فرض و تصمیم بعدی ثبت شد.');}catch(err){toast(err.message,true);b.disabled=false;}};
}
function showNextStep(){
 if(!S.phase_one||S.form?.kind==='report_review')return;
 const container=$('.form-foot');if(!container)return;
 $('#next-step')?.remove();
 const ids=S.form.kind==='item'?S.phase_one.item_ids:S.form.kind==='decision'?S.phase_one.psychometric_decision_ids:S.phase_one.case_ids;
 const next=ids.find(id=>reviewOf(S.form.kind,id)?.status!=='submitted');
 const button=document.createElement('button');button.id='next-step';button.type='button';button.className='btn';button.textContent=next?'نظر ثبت شد؛ رفتن به مورد بعدی':'این بخش تمام شد؛ بازگشت به راهنمای مراحل';
 button.onclick=()=>{if(next)navigate(S.form.kind==='item'?'bank':S.form.kind==='decision'?'decisions':'cases',next);else navigate('home');};container.append(button);
}
boot();
